###############################################################################
#  Packing problem for monomial ideals
#
#  Everything except `squarefree_gens` and `squarefree_in_codim` is computed
#  combinatorially from the supports of the minimal monomial generators: for a
#  monomial ideal, codim(I) is the minimal size of a set of variables meeting
#  every support (the minimal primes are generated by the minimal such sets),
#  and nonconstant monomials form a regular sequence iff their supports are pairwise
#  disjoint.
###############################################################################

@doc raw"""
    squarefree_gens(I::MPolyIdeal) -> Vector

Return the squarefree elements among the minimal monomial generators of the
monomial ideal `I`.

# Examples
```jldoctest
julia> R, (w, x, y, z) = polynomial_ring(GF(5), [:w, :x, :y, :z]);

julia> squarefree_gens(ideal(R, [y^2*z, x*y*w, z*w^3])) == [w*x*y]
true
```
"""
function squarefree_gens(I::MPolyIdeal)
  _check_ideal(I)
  @req is_monomial(I) "the ideal must be a monomial ideal"
  return [m for m in _minimal_monomial_generators(I) if all(<=(1), exponent_vector(m, 1))]
end

@doc raw"""
    squarefree_in_codim(I::MPolyIdeal) -> Vector

Return the squarefree minimal monomial generators of ``I^c``, where
``c = \operatorname{codim}(I)``. For a squarefree monomial ideal these are the
inclusion-minimal products of ``c`` minimal generators with pairwise disjoint
supports. For a general monomial ideal, only squarefree generators can occur
in such a product. The full ideal power is not constructed.

For the zero and unit ideals the result is `[one(base_ring(I))]` (the zeroth
power for the zero ideal).
"""
function squarefree_in_codim(I::MPolyIdeal)
  R = _check_ideal(I)
  @req is_monomial(I) "the ideal must be a monomial ideal"
  (is_zero(I) || _is_unit_ideal(I)) && return [one(R)]
  c = codim(I)
  G = squarefree_gens(I)
  length(G) < c && return elem_type(R)[]
  supports = [BitSet(findall(>(0), exponent_vector(m, 1))) for m in G]
  products = BitSet[]
  function search(start::Int, need::Int, used::BitSet)
    if need == 0
      push!(products, used)
      return nothing
    end
    for i in start:(length(supports) - need + 1)
      isdisjoint(used, supports[i]) || continue
      search(i + 1, need - 1, union(used, supports[i]))
    end
  end
  search(1, c, BitSet())
  x = gens(R)
  mons = [prod((x[i] for i in e); init=one(R)) for e in _minimal_sets(products)]
  return sort(mons; by=m -> (total_degree(m), exponent_vector(m, 1)))
end

# Inclusion-minimal sets among `E`, without repetitions.
function _minimal_sets(E::Vector{BitSet})
  E = unique(E)
  return [e for e in E if !any(f -> f != e && issubset(f, e), E)]
end

# Minimal size of a set of vertices meeting every edge in E (no edge empty):
# branch on the vertices of a smallest uncovered edge.
function _transversal_number(E::Vector{BitSet})
  best = Ref(typemax(Int))
  function search(edges::Vector{BitSet}, size::Int)
    size >= best[] && return nothing
    if isempty(edges)
      best[] = size
      return nothing
    end
    e = edges[argmin(length.(edges))]
    for v in e
      search([f for f in edges if !(v in f)], size + 1)
    end
  end
  search(E, 0)
  return best[]
end

# Are there `need` pairwise disjoint sets among supports[start:end], disjoint
# from `used`?
function _has_disjoint_supports(
  supports::Vector{BitSet}, start::Int, need::Int, used::BitSet
)
  need == 0 && return true
  length(supports) - start + 1 < need && return false
  for i in start:length(supports)
    isdisjoint(used, supports[i]) || continue
    _has_disjoint_supports(supports, i + 1, need - 1, union(used, supports[i])) &&
      return true
  end
  return false
end

# König property of the monomial ideal whose minimal generators have the
# supports E. An empty support means the unit ideal; no supports, the zero
# ideal. Both are König by convention.
function _is_konig_supports(E::Vector{BitSet})
  (isempty(E) || any(isempty, E)) && return true
  E = _minimal_sets(E)
  return _has_disjoint_supports(E, 1, _transversal_number(E), BitSet())
end

@doc raw"""
    is_konig(I::MPolyIdeal) -> Bool

Return whether the monomial ideal `I` is König, i.e. whether it contains a
regular sequence of ``\operatorname{codim}(I)`` monomials. Nonconstant monomials form a
regular sequence exactly when their supports are pairwise disjoint, so for the
edge ideal of a graph (or clutter) this means that the maximal number of
pairwise disjoint edges equals the minimal size of a vertex cover.

The generators need not be squarefree. The zero and unit ideals are König by
convention. The computation is purely combinatorial.

# Examples
```jldoctest
julia> R, (x, y, z) = polynomial_ring(QQ, [:x, :y, :z]);

julia> is_konig(ideal(R, [x*y, x*z, y*z]))
false

julia> is_konig(ideal(R, [x^2, y^2]))
true
```
"""
function is_konig(I::MPolyIdeal)
  _check_ideal(I)
  @req is_monomial(I) "the ideal must be a monomial ideal"
  return _is_konig_supports(_monomial_supports(I))
end

# Supports of a squarefree monomial ideal, renumbered on its active
# variables (those occurring in a minimal generator), and those variables.
function _active_supports(I::MPolyIdeal)
  @req is_monomial(I) "the ideal must be a monomial ideal"
  @req _is_squarefree_monomial_ideal(I) "packing requires a squarefree monomial ideal"
  E = _monomial_supports(I)
  active = sort!(collect(union(BitSet(), E...)))
  pos = Dict(v => k for (k, v) in enumerate(active))
  return [BitSet(pos[v] for v in e) for e in E], active
end

# The minor obtained by setting the variables in Z to 0 (deleting the edges
# meeting Z) and those in O to 1 (removing O from the remaining edges).
_minor(E::Vector{BitSet}, Z::BitSet, O::BitSet) =
  [setdiff(e, O) for e in E if isdisjoint(e, Z)]

# Visit all pairs (Z, O) of disjoint subsets of 1:a, starting with (∅, ∅);
# stop as soon as `f(Z, O)` returns true.
function _visit_substitutions(f, a::Int)
  state = zeros(Int8, a)
  while true
    Z = BitSet(i for i in 1:a if state[i] == 1)
    O = BitSet(i for i in 1:a if state[i] == 2)
    f(Z, O) && return nothing
    i = 1
    while i <= a && state[i] == 2
      state[i] = 0
      i += 1
    end
    i > a && return nothing
    state[i] += 1
  end
end

@doc raw"""
    is_packed(I::MPolyIdeal) -> Bool

Return whether the squarefree monomial ideal `I` is packed: every ideal
obtained from `I` by setting some variables to 0 and some other variables to 1
(a minor of the corresponding clutter) is König, see [`is_konig`](@ref).
Conforti and Cornuéjols conjectured that `I` is packed if and only if
``I^{(n)} = I^n`` for all `n`; this is not used by the package.

Only the variables occurring in the minimal generators matter, so at most
``3^a`` minors are examined, where ``a`` is their number; the search stops at
the first minor that is not König.

# Examples
```jldoctest
julia> R, (x, y, z, a, b) = polynomial_ring(QQ, [:x, :y, :z, :a, :b]);

julia> I = intersect(ideal(R, [x, y]), ideal(R, [x, z]), ideal(R, [z, a]),
                     ideal(R, [y, a]), ideal(R, [x, b]));

julia> is_packed(I)
true
```
"""
function is_packed(I::MPolyIdeal)
  _check_ideal(I)
  return isempty(non_packed_substitutions(I; first_only=true))
end

@doc raw"""
    non_packed_substitutions(I::MPolyIdeal; first_only::Bool = false)

Return the substitutions witnessing that the squarefree monomial ideal `I` is
not packed, as a vector of named tuples `(zero = [...], one = [...])` listing
the variables set to 0 and to 1. Only variables occurring in the minimal
generators of `I` are used, since the others do not change the ideal. The
trivial substitution (both lists empty) comes first and is present exactly when
`I` itself is not König. With `first_only = true` at most one substitution is
returned.

The result is empty exactly when `I` is packed. This combines `noPackedSub` and
`noPackedAllSubs` of the Macaulay2 package; unlike `noPackedAllSubs` it also
reports substitutions that only set variables to 0, or only to 1.

# Examples
```jldoctest
julia> R, (x, y, z) = polynomial_ring(QQ, [:x, :y, :z]);

julia> w = non_packed_substitutions(ideal(R, [x*y, x*z, y*z]));

julia> length(w) == 1 && isempty(w[1].zero) && isempty(w[1].one)  # only I itself fails
true

julia> S, v = polynomial_ring(QQ, :v => 1:6);

julia> two_triangles = intersect([ideal(S, [v[i], v[j]]) for (i, j) in
           [(1, 2), (2, 3), (1, 3), (3, 4), (4, 5), (5, 6), (4, 6)]]...);

julia> non_packed_substitutions(two_triangles; first_only = true)[1]
(zero = QQMPolyRingElem[], one = QQMPolyRingElem[])
```
"""
function non_packed_substitutions(I::MPolyIdeal; first_only::Bool=false)
  R = _check_ideal(I)
  E, active = _active_supports(I)
  x = gens(R)
  res = NamedTuple{(:zero, :one),Tuple{Vector{elem_type(R)},Vector{elem_type(R)}}}[]
  _visit_substitutions(length(active)) do Z, O
    if !_is_konig_supports(_minor(E, Z, O))
      push!(res, (zero=x[active[collect(Z)]], one=x[active[collect(O)]]))
      return first_only
    end
    return false
  end
  return res
end
